const projects=[
{name:'BudgetLens',type:'Mobile',date:'Aug — Dec 2026',ongoing:true,art:'budget',mark:'BudgetLens',caption:'A clearer view of everyday spending.',summary:'Android finance tracking, budgets & shared expenses',tags:['Kotlin','Android Development','Jetpack Compose','Material Design 3','CameraX'],description:'BudgetLens is an Android application designed to simplify personal finance tracking, budgeting, and shared expense management. It helps users record income and expenses, monitor category-based budgets, review financial summaries, and manage group spending.',details:'Built with Kotlin, Jetpack Compose, and Material Design 3, BudgetLens combines an intuitive interface with light and dark themes, responsive state management, input validation, and PDF reporting.',features:['Record income and expenses, track category-based budgets, and review financial summaries.','Split bills equally, by percentage, or by item and the quantity each participant receives.','Use receipt capture through CameraX to streamline transaction entry and bill creation.','Manage group spending and create PDF reports.'],integration:'BudgetLens also uses Supabase for authentication, persistent data storage, and synchronization of transactions, groups, and payment statuses across users.',github:'https://github.com/MarcellineYulencia/BudgetLens',apk:'assets/budgetlens/BudgetLens.apk',screens:[{id:'splash',label:'Welcome',alt:'BudgetLens welcome screen and logo'},{id:'login',label:'Login',alt:'BudgetLens login screen'},{id:'dashboard',label:'Dashboard',alt:'Complete BudgetLens dashboard including financial summary, budgets, and bottom navigation'}]},
{"name":"CampusShare","type":"UI/UX","date":"Feb — Jun 2026","art":"campus","summary":"Collaborative learning platform and AI learning assistant","tags":["Figma","User Interface Design","User Experience Design","Interactive Prototyping","Human Computer Interaction"],"description":"Designed CampusShare, a collaborative learning platform that helps students across universities in Serpong share resources, exchange ideas, and learn together. The concept brings course materials, discussion forums, and Campy, an AI learning assistant, into one connected experience.","paragraphs":["The interactive prototype covers verified student login, resource sharing by course and major, discussion forums, profiles, and personalized settings. Campy is designed to explain academic topics and help students explore learning materials, including PDFs, presentations, videos, and images.","Using the Genius Design methodology, the project developed personas, storyboards, user flows, and a high fidelity prototype in Figma. Shneiderman’s Eight Golden Rules and Gestalt Principles guided evaluation of consistency, feedback, navigation, and information organization."],"figma":"https://www.figma.com/design/oW8X8CF0Wv3nzTRnQEtR8w/CampusShare?node-id=460-423","phonePreview":true,"gallery":[{"src":"assets/campusshare/home.png","label":"Home","alt":"CampusShare home screen with shared learning materials and active discussions","phone":true},{"src":"assets/campusshare/resources.png","label":"Resources","alt":"CampusShare resource library with course materials and university filters","phone":true},{"src":"assets/campusshare/discussion.png","label":"Discussion","alt":"CampusShare discussion forum with course topics and student questions","phone":true},{"src":"assets/campusshare/campy.png","label":"Campy","alt":"Campy AI learning assistant prototype with academic question and answer interface","phone":true},{"src":"assets/campusshare/overview.png","label":"Design overview","alt":"Overview of CampusShare Figma screens, flows, and interface variations","phone":false}]},
{name:'ROMI Salon',type:'Web',date:'Aug — Dec 2025',art:'romi',mark:'ROMI',caption:'Your beauty. Our passion.',summary:'Salon booking & management system',tags:['React','Vite','Tailwind CSS','Node.js','Express','MySQL'],description:'A web based salon booking and management system connecting a customer booking experience with an integrated administration panel.',details:'Features include appointment availability validation, booking status management, services, stylists, transactions, inventory, analytics, loyalty points, vouchers, and reviews. Authentication uses JWT and bcrypt. Collaborators: Richard and Dwiky.'},
{"name":"Brain Tumor CAD","title":"Brain Tumor Segmentation And Classification With Two Stage Computer Aided Diagnosis","type":"AI / ML","date":"Aug — Dec 2026","ongoing":true,"art":"brain","mark":"Brain Tumor CAD","caption":"Segmentation and classification from MRI images","summary":"Brain tumor segmentation and classification from MRI images","tags":["Python","PyTorch","Computer Vision","Deep Learning","Medical Image Segmentation"],"description":"Developed a deep learning pipeline with two stages for brain tumor segmentation and classification from MRI images. Attention U Net segments tumor regions and extracts regions of interest. An ensemble of EfficientNet B4 and ResNet 50 then classifies images as glioma, meningioma, pituitary, or no tumor.","details":"The project included data preprocessing, augmentation, checks for duplicates and data leakage, fine tuning in stages, and ensemble weighting based on validation results. Performance was evaluated using confusion matrices, ROC curves, error analysis, and Grad CAM visualizations.","results":"Achieved 88.63% accuracy and a Macro F1 score of 0.8805 on an internal test set of 1,311 images.","github":"https://github.com/MarcellineYulencia/Brain-Tumor-Model","gallery":[{"src":"assets/brain-tumor/04-attention-unet.png","label":"Attention U Net","alt":"Python implementation of the Attention U Net architecture"},{"src":"assets/brain-tumor/01-training.png","label":"Segmentation training","alt":"Python segmentation training loop and evaluation"},{"src":"assets/brain-tumor/02-loss.png","label":"Loss and training setup","alt":"Dice loss, segmentation metrics, early stopping and optimizer setup"},{"src":"assets/brain-tumor/03-roi.png","label":"Region extraction","alt":"MRI probability prediction and region of interest extraction code"},{"src":"assets/brain-tumor/05-ensemble.png","label":"Ensemble evaluation","alt":"Ensemble weighting and classification evaluation code"}],"metrics":[{"value":"88.63%","label":"Accuracy"},{"value":"0.8805","label":"Macro F1"},{"value":"1,311","label":"Internal test images"}]},
{"name":"Coronary Stenosis Detection","title":"Coronary Stenosis Detection from Angiogram Images","type":"AI / ML","date":"Feb — Jun 2026","art":"coronary","summary":"Deep learning classification and interpretation of coronary angiogram images","tags":["Python","PyTorch","Deep Learning","Computer Vision","Explainable AI"],"description":"Developed a deep learning pipeline in Python and PyTorch to classify coronary angiogram images as Stenosis or No Stenosis. A pretrained EfficientNet B4 backbone and a custom classification head connect image preparation, model training, evaluation, and prediction interpretation.","metrics":[{"value":"99.12%","label":"Test accuracy"},{"value":"0.9912","label":"Macro F1"},{"value":"0.9995","label":"ROC AUC"}],"results":"Recorded 99.12% accuracy, a Macro F1 of 0.9912, 99.13% balanced accuracy, and a ROC AUC of 0.9995 on the project’s test set using augmentation during inference. Recall was 99.08% for stenosis and 99.17% for images without stenosis.","paragraphs":["The dataset contained 6,881 images, split into 4,829 for training, 1,025 for validation, and 1,027 for testing. Data augmentation, weighted sampling, and fine tuning in three phases supported training and addressed class imbalance.","Grad CAM heatmaps highlighted regions influencing each prediction. Confusion matrices, ROC curves, and misclassified image reviews supported evaluation. Inference for individual images and batches returns labels, confidence scores, and class probabilities, with saved checkpoints and prediction exports supporting reproducibility."],"github":"https://github.com/MarcellineYulencia/Coronary-Stenosis-Detector-Model.git","gallery":[{"src":"assets/coronary/architecture.png","label":"Model architecture","alt":"EfficientNet B4 backbone and custom binary classification head in PyTorch"},{"src":"assets/coronary/preprocessing.png","label":"Preprocessing","alt":"Conservative angiogram preprocessing and data augmentation pipeline"},{"src":"assets/coronary/loss.png","label":"Training criterion","alt":"Weighted classification loss and label smoothing implementation"},{"src":"assets/coronary/training.png","label":"Training loop","alt":"PyTorch training loop with MixUp and gradient clipping"},{"src":"assets/coronary/gradcam.png","label":"Grad CAM","alt":"Grad CAM implementation for interpreting model predictions"}]},
{"name":"Farm Guardian","type":"Game","date":"Aug — Dec 2026","ongoing":true,"art":"farm","summary":"3D Farming & Animal Rescue Adventure","tags":["Unity","C#","3D Game Development","Gameplay Programming","Game State Management"],"description":"Farm Guardian is a 3D farming and animal rescue game built with Unity and C#. Players explore the farm, bring animals to safety, protect them from thieves, and plant seeds while racing against the clock. Each level asks players to balance exploration, resource management, and quick decisions.","paragraphs":["A level progression system rewards performance with stars and encourages players to revisit challenges. Unlockable upgrades, character skins, and locally saved progress add personalization and a sense of growth between sessions.","The project connects player movement, interactive objects, rescue mechanics, thief catching, and timed objectives through coordinated game states. A cozy visual style, clear HUD, and accessible controls support the experience, with automated PlayMode tests and a Windows build workflow supporting development."],"github":"https://github.com/MarcellineYulencia/Farm-Guardian.git","windows":"assets/farmguardian/Farm-Guardian-Windows.zip","gallery":[{"src":"assets/farmguardian/main-menu.png","label":"Main menu","alt":"Farm Guardian main menu with start, upgrades, and settings"},{"src":"assets/farmguardian/level-select.png","label":"Level selection","alt":"Farm Guardian level progression map with star rewards"},{"src":"assets/farmguardian/objectives.png","label":"Level objectives","alt":"Farm Guardian rescue objectives and countdown for a level"},{"src":"assets/farmguardian/gameplay.png","label":"Farm exploration","alt":"3D Farm Guardian gameplay showing player, animals, pens, timer, and HUD"},{"src":"assets/farmguardian/animal-rescue.png","label":"Animal rescue","alt":"Carrying a rescued animal to its pen in Farm Guardian"},{"src":"assets/farmguardian/catch-thief.png","label":"Protecting animals","alt":"Farm Guardian thief catching interaction and rescued animal progress"}]},
{"name":"Ucup Menjelajah Nusantara","type":"Game","date":"Feb — Jun 2025","art":"ucup","mark":"Ucup Menjelajah Nusantara","summary":"A Web-Based Educational Adventure Game","tags":["React.js","JavaScript","React Context API","HTML","CSS"],"description":"An adventure game built with React.js that brings exploration, character management, and interactive minigames into one playful world. Players create a character and explore a house, market, beach, forest, and mine while gathering resources and discovering activities along the way.","paragraphs":["Every choice affects four essential needs: hunger, sleep, happiness, and hygiene. Players balance mining, swimming, and trading with everyday routines such as eating and resting. A shared inventory connects each location, while the final Life Satisfaction Score reflects their journey.","Reusable React components and the React Context API keep gameplay and character state connected across locations. Character animations, a cycle of day and night, and background music bring the world to life."],"github":"https://github.com/MarcellineYulencia/Ucup-Menjelajah-Nusantara.git","website":"https://exquisite-kelpie-3497d8.netlify.app/","gallery":[{"src":"assets/ucup/exploration.png","label":"Exploration","alt":"Ucup exploring the outdoor game world with character needs and inventory controls"},{"src":"assets/ucup/house.png","label":"House","alt":"House interior with eating, sleeping, bathing, and inventory activities"},{"src":"assets/ucup/beach.png","label":"Beach","alt":"Beach location with swimming, surfing, and other activities"},{"src":"assets/ucup/market.png","label":"Market","alt":"Traditional market location with resource trading"},{"src":"assets/ucup/forest.png","label":"Forest","alt":"Forest exploration and interaction with characters"},{"src":"assets/ucup/mine.png","label":"Mine","alt":"Mine location with mining activities and a minigame"}]}
];
projects.push({"name": "Sadaru", "type": "UI/UX", "date": "September 2026", "phonePreview": true, "summary": "A financial wellbeing app concept for more mindful spending", "tags": ["Figma", "User Interface Design", "User Experience Design", "Behavioral Design", "Interactive Prototyping"], "description": "Designed Sadaru with team ChachiMaky for the ISFEST 2026 UI/UX Competition. The mobile app concept addresses the gap between financial knowledge and everyday spending habits, helping young adults pause before an impulsive purchase and build more intentional saving routines.", "paragraphs": ["The Figma prototype connects a shopping trigger quiz with financial weather check ins, Radar Belanja, and Jeda Sadar, a short reflection before buying. Users can set a waiting period for tempting purchases, explore visual savings jars, and review weekly insights that connect spending patterns with mood.", "Behavioral principles such as habit loops, commitment devices, and mental accounting guided the interaction design. A warm palette of moss green, gold, and terracotta pairs with weather and savings jar metaphors to make financial reflection feel approachable. Supportive language and visible choices preserve user autonomy throughout the experience."], "figma": "https://www.figma.com/design/d9diqXszCDZDWM7pjpNguP/Lomba-UI-UX-ISFEST?node-id=10-540", "participation": "https://drive.google.com/file/d/1Kc7gKpLf2b7Dldm4M314g3M1nVcWmcTj/view?usp=drivesdk", "gallery": [{"src": "assets/sadaru/home.png", "label": "Home", "alt": "Sadaru home concept with financial weather, shopping radar, and daily progress", "phone": true}, {"src": "assets/sadaru/savings.png", "label": "Savings jars", "alt": "Sadaru visual savings jars for emergency funds, a holiday, and personal goals", "phone": true}, {"src": "assets/sadaru/insights.png", "label": "Weekly insights", "alt": "Sadaru weekly insights showing spending and mood patterns in the prototype", "phone": true}, {"src": "assets/sadaru/overview.png", "label": "Design overview", "alt": "Overview of Sadaru Figma screens covering onboarding, mindful spending, savings jars, and weekly insights", "phone": false}]});
const startDates={'BudgetLens':'2026-08','Brain Tumor CAD':'2026-08','Farm Guardian':'2026-08','CampusShare':'2026-02','Coronary Stenosis Detection':'2026-02','ROMI Salon':'2025-08','Ucup Menjelajah Nusantara':'2025-02'};
projects.forEach(p=>p.startDate=p.name==='Sadaru'?'2026-09':startDates[p.name]);
projects.sort((a,b)=>b.startDate.localeCompare(a.startDate));
// Keep the competition design immediately after Ucup, as requested.
const sadaruIndex=projects.findIndex(p=>p.name==='Sadaru');
const [sadaru]=projects.splice(sadaruIndex,1);
projects.splice(projects.findIndex(p=>p.name==='Ucup Menjelajah Nusantara')+1,0,sadaru);
const grid=document.querySelector('#project-grid'),dialog=document.querySelector('dialog');
function phone(screen){return `<div class="phone-frame"><div class="phone-screen"><img src="${screen.src||`assets/budgetlens/${screen.id}.svg`}" alt="${screen.alt}" loading="lazy" width="360" height="760"></div></div>`}
function openProject(p){
 const hasGallery=!!(p.screens||p.gallery);
 dialog.classList.toggle('project-dialog-wide',hasGallery);
 dialog.classList.toggle('research-dialog',!!p.gallery);
 dialog.classList.toggle('game-dialog',p.type==='Game');
 dialog.classList.toggle('campus-dialog',!!p.phonePreview);
 const heading=`<span class="eyebrow">${p.type} / ${p.date}</span><h2 id="project-title">${p.title||p.name}</h2>${p.subtitle?`<p class="project-subtitle">${p.subtitle}</p>`:''}`;
 const skills=`<div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>`;
 const content=document.querySelector('#dialog-content');
 const links=`<div class="project-links">${p.windows?`<a class="button primary" href="${p.windows}" download="Farm-Guardian-Windows.zip">Download for Windows ↓</a>`:''}${p.figma?`<a class="button primary" href="${p.figma}" target="_blank" rel="noopener">View in Figma ↗</a>`:''}${p.website?`<a class="button primary" href="${p.website}" target="_blank" rel="noopener">Play game ↗</a>`:''}${p.apk?`<a class="button primary" href="${p.apk}" download="BudgetLens.apk">Download APK ↓</a>`:''}${p.participation?`<a class="button secondary" href="${p.participation}" target="_blank" rel="noopener">View participation ↗</a>`:''}${p.github?`<a class="button secondary" href="${p.github}" target="_blank" rel="noopener">View GitHub ↗</a>`:''}</div>${p.apk?'<p class="download-info">Android APK · 15.4 MB</p>':''}${p.windows?'<p class="download-info">Windows 64 bit · ZIP build. Extract the entire folder, then run FarmGuardian.exe.</p>':''}`;
 if(hasGallery){
  const items=p.screens||p.gallery;
  const imageMarkup=s=>p.screens||s.phone?phone(s):`<a class="research-image-link" href="${s.src}" target="_blank" rel="noopener" aria-label="Open full screenshot: ${s.label}"><img src="${s.src}" alt="${s.alt}"><span>Open full image ↗</span></a>`;
  const gallery=`<div class="project-gallery ${p.gallery?'research-gallery':''}"><div id="gallery-image">${imageMarkup(items[0])}</div><div class="gallery-controls"><button class="gallery-arrow" data-direction="-1" aria-label="Previous image">←</button><p class="gallery-caption" role="status" aria-live="polite">${items[0].label} · 1 / ${items.length}</p><button class="gallery-arrow" data-direction="1" aria-label="Next image">→</button></div></div>`;
  const body=p.screens?`<p>${p.description}</p><h3>What it does</h3><ul class="detail-list">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><p>${p.details}</p><p>${p.integration}</p>`:`<p>${p.description}</p>${p.results?`<div class="research-metrics">${p.metrics.map(m=>`<div><strong>${m.value}</strong><span>${m.label}</span></div>`).join('')}</div><p>${p.results}</p>`:''}${(p.paragraphs||[p.details]).filter(Boolean).map(text=>`<p>${text}</p>`).join('')}`;
  content.innerHTML=heading+`<div class="project-detail-layout">${gallery}<div class="detail-copy"><span class="detail-status">${p.name==='Sadaru'?'Competition prototype · '+p.date:p.ongoing?'In progress · Completion December 2026':'Completed · '+p.date}</span>${body}<h3>${p.tags.length===5?'Top 5 skills':'Skills'}</h3>${skills}${links}</div></div>`;
  let current=0;
  const changeImage=direction=>{current=(current+direction+items.length)%items.length;content.querySelector('#gallery-image').innerHTML=imageMarkup(items[current]);content.querySelector('.gallery-caption').textContent=`${items[current].label} · ${current+1} / ${items.length}`};
  content.querySelectorAll('[data-direction]').forEach(b=>b.addEventListener('click',()=>changeImage(Number(b.dataset.direction))));
  content.querySelector('.project-gallery').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();changeImage(e.key==='ArrowLeft'?-1:1)}});
 }else content.innerHTML=heading+`<p>${p.description}</p>${skills}<p>${p.details}</p>${links}`;
 dialog.showModal();dialog.scrollTop=0;
}

function render(filter='All'){
 grid.replaceChildren();
 projects.forEach((p,i)=>{
  if(filter!=='All'&&p.type!==filter&&!(filter==='Web'&&p.name==='Ucup Menjelajah Nusantara'))return;
  const card=document.createElement('button');card.className='project-card';card.setAttribute('aria-label',`Read about ${p.name}`);
  const artwork=p.phonePreview?`<div class="project-art budget-preview campus-preview ${p.name==='Sadaru'?'sadaru-preview':''}"><small>${String(i+1).padStart(2,'0')} / UI/UX</small>${[p.gallery[0],p.gallery[1],p.gallery.filter(s=>s.phone)[3]||p.gallery[2]].map(phone).join('')}</div>`:p.gallery?`<div class="project-art research-preview"><small>${String(i+1).padStart(2,'0')} / ${p.type.toUpperCase()}</small><img src="${p.gallery[0].src}" alt="${p.gallery[0].alt}" loading="lazy">${p.results?`<span class="research-result">${p.metrics[0].value} accuracy <span>Project test set</span></span>`:`<span class="research-result">${p.windows?'3D farming and rescue':'Interactive adventure'} <span>${p.windows?'Unity · C#':'React.js'}</span></span>`}</div>`:p.screens?`<div class="project-art budget-preview"><small>${String(i+1).padStart(2,'0')} / MOBILE</small>${p.screens.map(phone).join('')}</div>`:`<div class="project-art ${p.art}"><small>${String(i+1).padStart(2,'0')} / ${p.type.toUpperCase()}</small><span class="project-mark">${p.mark}</span><span class="art-bottom">${p.caption}</span></div>`;
  card.innerHTML=artwork+`<div class="project-meta"><span>${p.date}</span><span class="${p.ongoing?'progress':''}">${p.ongoing?'● In progress':'Completed'}</span></div><h3>${p.name}<span>↗</span></h3><p>${p.summary}</p><div class="tags card-tags">${p.tags.slice(0,p.screens||p.gallery?5:3).map(t=>`<span>${t}</span>`).join('')}</div><span class="project-read">Explore project <span>↗</span></span>`;
  card.addEventListener('click',()=>openProject(p));grid.append(card);
 });
}
render();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render(b.dataset.filter)}));document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close −':'Menu +'};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu +'}));
document.querySelector('#copy-email').onclick=async()=>{try{await navigator.clipboard.writeText('marcellineyulencia@gmail.com');document.querySelector('#copy-status').textContent='Email copied!'}catch{document.querySelector('#copy-status').textContent='marcellineyulencia@gmail.com'}};
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-20% 0px -60% 0px'});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));

 document.querySelector("#contact-form").addEventListener("submit",e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=data.get("name").trim(),email=data.get("email").trim(),message=data.get("message").trim();if(!name||!message){document.querySelector("#form-status").textContent="Please enter your name and message.";return}const subject=encodeURIComponent("Portfolio enquiry from "+name);const body=encodeURIComponent(message+"\n\n"+name+"\n"+email);window.location.href="mailto:marcellineyulencia@gmail.com?subject="+subject+"&body="+body;document.querySelector("#form-status").textContent="Your email app has been requested. Review the draft and press Send there. If no app opens, use the email link to contact me."});
